using FamilyVeda.Api.Background;
using FamilyVeda.Application.Agents;
using FamilyVeda.Application.Common;
using FamilyVeda.Application.Records;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Records;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Records;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;

namespace FamilyVeda.UnitTests;

public sealed class LabExtractionWorkerTests
{
    [Fact]
    public async Task Recovery_RequeuesRecentReadsAndFailsStaleOnesAsInterrupted()
    {
        using var provider = BuildProvider(new CountingAgent());
        Guid recentId, staleId, completedId;
        await using (var scope = provider.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var member = SeedMember(db);
            var recent = Report(member, OcrStatus.Processing);
            var stale = Report(member, OcrStatus.Processing);
            var completed = Report(member, OcrStatus.Completed);
            db.LabReports.AddRange(recent, stale, completed);
            await db.SaveChangesAsync();
            // Synchronous SaveChanges does not restamp UpdatedAt: simulate a read cut off long ago.
            stale.UpdatedAt = DateTimeOffset.UtcNow - OcrFailureCodes.StaleProcessingAfter - TimeSpan.FromMinutes(1);
            db.SaveChanges();
            (recentId, staleId, completedId) = (recent.Id, stale.Id, completed.Id);
        }
        var worker = new LabExtractionWorker(new LabExtractionQueue(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<LabExtractionWorker>.Instance);

        var recovered = await worker.RecoverInterruptedReportsAsync(CancellationToken.None);

        recovered.Should().Equal(recentId);
        await using var verify = provider.CreateAsyncScope();
        var reports = await verify.ServiceProvider.GetRequiredService<AppDbContext>().LabReports.ToDictionaryAsync(x => x.Id);
        reports[recentId].OcrStatus.Should().Be(OcrStatus.Processing);
        reports[staleId].OcrStatus.Should().Be(OcrStatus.Failed);
        reports[staleId].OcrErrorCode.Should().Be(OcrFailureCodes.Interrupted);
        reports[completedId].OcrStatus.Should().Be(OcrStatus.Completed);
    }

    [Fact]
    public async Task Worker_DrainsTheQueueAndCompletesReportsInItsOwnScope()
    {
        var agent = new CountingAgent();
        using var provider = BuildProvider(agent);
        Guid reportId;
        await using (var scope = provider.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var report = Report(SeedMember(db), OcrStatus.Pending);
            db.LabReports.Add(report);
            await db.SaveChangesAsync();
            reportId = report.Id;
            await scope.ServiceProvider.GetRequiredService<ILabExtractionService>().ExtractAsync(reportId, CancellationToken.None);
        }
        var worker = new LabExtractionWorker(provider.GetRequiredService<ILabExtractionQueue>(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<LabExtractionWorker>.Instance);

        await worker.StartAsync(CancellationToken.None);
        var deadline = DateTime.UtcNow.AddSeconds(5);
        OcrStatus status;
        do
        {
            await Task.Delay(20);
            await using var check = provider.CreateAsyncScope();
            status = (await check.ServiceProvider.GetRequiredService<AppDbContext>().LabReports.AsNoTracking().SingleAsync(x => x.Id == reportId)).OcrStatus;
        } while (status == OcrStatus.Processing && DateTime.UtcNow < deadline);
        await worker.StopAsync(CancellationToken.None);

        status.Should().Be(OcrStatus.Completed);
        agent.Calls.Should().Be(1);
    }

    private static ServiceProvider BuildProvider(IAgent agent)
    {
        var services = new ServiceCollection();
        var databaseName = Guid.NewGuid().ToString();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase(databaseName));
        services.AddSingleton<ILabExtractionQueue, LabExtractionQueue>();
        services.AddSingleton(agent);
        services.AddScoped<ICurrentUser, SyntheticHead>();
        services.AddScoped<ILabExtractionService, LabExtractionService>();
        return services.BuildServiceProvider();
    }

    private static Member SeedMember(AppDbContext db)
    {
        var user = new UserAccount { Id = SyntheticHead.Id, Email = $"synthetic-{Guid.NewGuid():N}@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Worker Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        db.AddRange(user, family, member);
        return member;
    }

    private static LabReport Report(Member member, OcrStatus status) => new()
    {
        Member = member, OriginalFileName = "synthetic.png", StoredFileName = "db:synthetic.png", ContentType = "image/png", SizeBytes = 100, OcrStatus = status
    };

    private sealed class CountingAgent : IAgent
    {
        public int Calls;
        public AgentKind Kind => AgentKind.Extraction;
        public Task<AgentRunResult> RunAsync(AgentRunContext context, CancellationToken cancellationToken)
        {
            Interlocked.Increment(ref Calls);
            return Task.FromResult(new AgentRunResult(Kind, "{\"valuesExtracted\":1,\"flagsExtracted\":0}", 1m, [], [], [], true));
        }
    }

    private sealed class SyntheticHead : ICurrentUser
    {
        public static readonly Guid Id = Guid.Parse("00000000-0000-0000-0000-0000000000a1");
        public bool IsAuthenticated => true;
        public Guid UserId => Id;
        public UserType UserType => UserType.FamilyUser;
    }
}
